'use strict';
const OperationsReportHub={
 state:null,epoch:0,busy:false,
 esc:v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),
 money:v=>v==null?'未设定':'¥'+Number(v).toLocaleString('zh-CN',{maximumFractionDigits:2}),
 day:()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date()),
 add:(v,n)=>new Date(Date.parse(v+'T12:00:00Z')+n*86400000).toISOString().slice(0,10),
 $(id){return document.getElementById('rh-'+id);},
 api(method,path,body){return Store._request(method,'/rest/v1/'+path,body);},
 async render(){
  if(!Auth.canReadOperationsReports())return;OperationsItemAnalysis.dispose();this.close();const today=this.day(),weekday=new Date(today+'T12:00:00Z').getUTCDay();
  this.state={month:today.slice(0,7),week:this.add(today,-((weekday+6)%7)-7),tab:'overview',kind:'',query:'',offset:0};
  this.$root=document.getElementById('page-operations');this.$root.innerHTML='<div class="report-hub"><header class="rh-heading"><div><h1>经营分析报告</h1><p>复盘经营，检查行动，安排下周。</p></div><div class="rh-controls"><label class="rh-sr" for="rh-month">经营月份</label><input id="rh-month" type="month" value="'+today.slice(0,7)+'"><button id="rh-set" class="rh-outline"'+(Auth.isAdmin?'':' hidden')+'>设置月度目标</button></div></header><div class="rh-tabs" role="tablist">'+[['overview','经营概览'],['archive','报告档案'],['targets','月度目标']].map(([v,n])=>'<button role="tab" id="rh-tab-'+v+'" data-tabvalue="'+v+'" aria-selected="'+(v==='overview')+'">'+n+'</button>').join('')+'</div><p id="rh-status" role="status" aria-live="polite"></p><div id="rh-content"></div><details class="rh-maintenance"><summary>其他分析与维护</summary><button id="rh-tools" class="rh-text">月报、专项及数据核对工具</button></details></div>';
  this.$('month').onchange=()=>{if(!this.$('month').value)return;this.state.month=this.$('month').value;this.state.offset=0;this.load();};
  this.$('set').onclick=()=>this.target(this.state.month);this.$('tools').onclick=()=>{this.epoch++;this.close();OperationsReportCenter.renderTools();};
  for(const el of this.$root.querySelectorAll('[data-tabvalue]'))el.onclick=()=>{this.state.tab=el.dataset.tabvalue;this.state.offset=0;this.load();};await this.load();
 },
 async load(){const epoch=++this.epoch,s={...this.state};this.$('status').textContent='正在读取正式资料…';for(const el of this.$root.querySelectorAll('[role=tab]'))el.setAttribute('aria-selected',el.dataset.tabvalue===s.tab);this.$('content').innerHTML='';
  try{const summary=await this.api('GET','report-center?month='+s.month);if(epoch!==this.epoch||!this.$('content'))return;this.summary=summary;
   if(s.tab==='overview')await this.overview(epoch);else if(s.tab==='targets')this.targets();else await this.archive(epoch);
   if(epoch===this.epoch&&this.$('status'))this.$('status').textContent='';
  }catch(e){if(epoch===this.epoch&&this.$('status')){this.$('status').textContent='资料读取未完成：'+e.message;this.$('content').innerHTML='<button class="rh-outline" id="rh-retry">重新读取</button>';this.$('retry').onclick=()=>this.load();}}
 },
 reportRows(rows){const h=this.esc;return rows.length?rows.map(r=>'<article class="rh-report-row"><div><b>'+h(r.startDate)+' — '+h(r.endDate)+'</b><small>'+h(r.title)+'</small></div><span class="rh-badge">'+OperationsReportCenter.label(r.reportType)+' · v'+h(r.reportVersion)+'</span><button class="rh-text" data-report="'+h(r.id)+'">阅读 →</button></article>').join(''):'<p class="rh-muted">暂无符合条件的正式报告。</p>';},
 bindReports(){for(const b of this.$root.querySelectorAll('[data-report]'))b.onclick=()=>OperationsReportCenter.openReport(b.dataset.report);},
 dailyStatus(r){return !r.finalized?'暂报':r.revision>1?'已修订 · v'+r.revision:'正式';},
 async overview(epoch){const h=this.esc,m=this.money,d=this.summary;
  const [reports,daily]=await Promise.all([this.api('GET','operations-reports?latest=1&limit=3'),this.api('GET','daily-briefs?limit=1')]);if(epoch!==this.epoch)return;
  this.$('content').innerHTML='<section class="rh-summary">'+[['月收入目标',m(d.target)],['本月实际',d.actual==null?'—':m(d.actual)],['完成',d.completion==null?'—':(d.completion*100).toFixed(1)+'%'],[d.gap<0?'超额':'尚差',d.gap==null?'—':m(Math.abs(d.gap))]].map(([k,v])=>'<div><span>'+k+'</span><strong>'+v+'</strong></div>').join('')+'<small>'+(d.cutoff?'截至'+h(d.cutoff)+' · 查询时点快照':'未来月份，尚无收入快照')+'</small></section><p class="rh-basis">'+h(d.basis)+'</p><div class="rh-daily-latest"><div><span class="rh-badge">日报</span><b>'+(daily.reports[0]?h(daily.reports[0].business_date)+'经营日报':'尚无归档日报')+'</b><span class="rh-muted">'+(daily.reports[0]?this.dailyStatus(daily.reports[0]):'')+'</span></div>'+(daily.reports[0]?'<button id="rh-latest-daily" class="rh-text">阅读日报 →</button>':'')+'</div><section class="rh-panel"><div class="rh-section-title"><h2>本期周报</h2><label class="rh-week-label">复盘周（选择周一）<input id="rh-week" type="date" value="'+h(this.state.week)+'"></label></div><div id="rh-week-body">正在核对周报进度与七天日报…</div></section><section class="rh-panel"><div class="rh-section-title"><h2>最近正式报告</h2><button class="rh-text" id="rh-all">查看全部 →</button></div>'+this.reportRows(reports.reports)+'</section>';
  this.$('latest-daily')?.addEventListener('click',()=>this.daily(daily.reports[0].id));this.$('all').onclick=()=>{this.state.tab='archive';this.load();};this.bindReports();
  this.$('week').onchange=()=>{const value=this.$('week').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(value)||new Date(value+'T12:00:00Z').getUTCDay()!==1||this.add(value,6)>=this.day()){this.$('week').value=this.state.week;UI.toast('请选择已经结束的一周的周一','error');return;}this.state.week=value;this.week(epoch);};await this.week(epoch);
 },
 async week(epoch){const start=this.state.week,h=this.esc,body=this.$('week-body');if(!body)return;body.textContent='正在核对周报进度与七天日报…';
  const canPrepare=Auth.canAccessOperations();try{const dailyPromise=canPrepare?this.api('GET','daily-briefs?week='+start):Promise.resolve(null),[data,daily]=await Promise.all([canPrepare?this.api('GET','weekly-management?start='+start):Promise.resolve(null),dailyPromise]);if(epoch!==this.epoch||start!==this.state.week||!this.$('week-body'))return;this.weekData=data;this.weekDaily=daily;const run=data?.runs?.[0];this.run=run;
   const states={prepared:'等待在Codex发起分析',analyzed:'草稿已完成，待阅读复核',reviewed:'已复核，待正式发布',published:'已发布'};
   this.$('week-body').innerHTML='<p class="rh-period">'+h(start)+' — '+h(this.add(start,6))+'</p><span class="rh-badge rh-amber">'+(data?(run?states[run.state]:'待补充情况并准备资料'):'请阅读已发布报告；准备工作仅向运营账号开放')+'</span>'+(daily?'<div class="rh-coverage"><div><b>本周日报资料</b><small>正式'+(daily.reports.filter(r=>r.finalized).length)+'天（含修订'+daily.reports.filter(r=>r.revision>1&&r.finalized).length+'天） · 暂报'+daily.provisionalDates.length+'天 · 缺失'+daily.missing.length+'天 · 待修订'+daily.stale.length+'天</small></div><button class="rh-text" id="rh-coverage">查看七天资料 →</button></div>':'')+(data?'<ol class="rh-steps"><li class="'+(run?'done':'')+'">补充情况<small>'+(run?'已保存':'可选补充，提交后准备')+'</small></li><li class="'+(run?.analysis?'done':'')+'">Agent分析<small>'+(run?.analysis?'已有草稿':'等待在Codex发起')+'</small></li><li class="'+(run?.state==='published'?'done':'')+'">阅读与发布<small>'+(run?.state==='published'?'已发布':run?.analysis?'待管理员复核':'生成后可查看')+'</small></li></ol><div class="rh-actions">'+(run?'<button class="rh-primary" id="rh-copy">复制分析请求</button>':'')+'<button class="'+(run?'rh-text':'rh-primary')+'" id="rh-note">'+(run?'补充本期情况':'补充情况，准备周报')+'</button>'+(run?.analysis?'<button id="rh-workspace" class="rh-outline">阅读与发布</button>':'')+'</div><p class="rh-muted">当前分析由Codex发起。'+(data.todos?.length?'待办：'+h(data.todos.join('；')):'')+'</p>':'');
   this.$('coverage')?.addEventListener('click',()=>this.coverage());this.$('note')?.addEventListener('click',()=>this.note());this.$('copy')?.addEventListener('click',()=>this.copy());this.$('workspace')?.addEventListener('click',()=>window.open('weekly-management.html?start='+encodeURIComponent(start),'_blank'));
  }catch(e){if(epoch===this.epoch&&start===this.state.week&&this.$('week-body')){this.$('week-body').textContent='周资料核对未完成：'+e.message;}}
 },
 dialog(title,html){this.close();const el=document.createElement('dialog');el.id='rh-dialog';el.className='rh-dialog';el.innerHTML='<header><h2>'+this.esc(title)+'</h2><button class="rh-text" aria-label="关闭">关闭 ×</button></header>'+html;document.body.appendChild(el);el.querySelector('header button').onclick=()=>this.close();el.addEventListener('cancel',e=>{if(this.busy)e.preventDefault();});el.addEventListener('close',()=>el.remove());el.showModal();return el;},
 close(){const el=document.getElementById('rh-dialog');if(el){el.close();el.remove();}},
 async note(){const start=this.state.week,h=this.esc,text=this.weekData?.operatorInput?.text||'';const el=this.dialog('补充本期情况','<p class="rh-muted">只需写一段您想说明的情况。事情、判断、疑问或想法可以混写，Agent会先整理再分析；无需重复填写系统收入和日报。</p><label for="rh-note-input">本期补充（选填）</label><textarea id="rh-note-input" rows="7" maxlength="6000">'+h(text)+'</textarea><p id="rh-dialog-status" role="status"></p><div class="rh-actions"><button id="rh-submit" class="rh-primary">保存补充，准备资料</button></div>');
  let requestId=crypto.randomUUID();el.querySelector('#rh-submit').onclick=async()=>{if(this.busy)return;this.busy=true;for(const b of el.querySelectorAll('button'))b.disabled=true;el.querySelector('textarea').disabled=true;const status=el.querySelector('[role=status]');status.textContent='正在保存原文并封存业务资料…';try{await this.api('POST','weekly-management',{action:'submit-input',start,text:el.querySelector('textarea').value,requestId});this.close();await this.week(this.epoch);UI.toast('补充和资料已保存，请复制分析请求到Codex。');}catch(e){status.textContent=e.message;}finally{this.busy=false;for(const b of el.querySelectorAll('button'))b.disabled=false;el.querySelector('textarea').disabled=false;}};
  el.querySelector('textarea').oninput=()=>{requestId=crypto.randomUUID();};
 },
 async copy(){const run=this.run;if(!run)return;const text='请按周报标准版1.0，分析艾维美术馆'+this.state.week+'至'+this.add(this.state.week,6)+'的经营情况。读取正式周报准备记录 '+run.id+'，来源快照 '+(run.sha256||run.payload?.sha256||'请以接口为准')+'；先清理已保存的运营补充，承接七天日报、上期行动与预测和月度目标。资料不足需明确待办。保存待复核草稿，不自动发布或群发。';try{await navigator.clipboard.writeText(text);UI.toast('已复制，请粘贴到Codex发起分析。');}catch{const el=this.dialog('复制分析请求','<p>请选择下方内容，复制到Codex。</p><textarea rows="8" readonly>'+this.esc(text)+'</textarea>');el.querySelector('textarea').select();}},
 coverage(){const h=this.esc,d=this.weekDaily;this.dialog('本周七天日报资料','<p class="rh-muted">读取最新有效日报。日报提供经营背景，周收入仍以统一正式快照核对。</p><div class="rh-days">'+Array.from({length:7},(_,i)=>{const date=this.add(this.state.week,i),r=d.reports.find(x=>x.date===date);return '<div><b>'+h(date)+'</b><span class="rh-badge'+(!r||!r.finalized||d.stale.includes(date)?' rh-amber':'')+'">'+(!r?'缺失':d.stale.includes(date)?'待修订':this.dailyStatus(r))+'</span>'+(r?'<button class="rh-text" data-daily="'+h(r.id)+'">查看 →</button>':'<small>背景资料待补充，不能按零收入处理。</small>')+'</div>';}).join('')+'</div><p class="rh-footnote">保留每份日报当时的天气、库存和截止信息。缺失或暂报时，已有小计不能代替完整周数据。</p>');this.bindDaily(document.getElementById('rh-dialog'));},
 bindDaily(root){for(const b of root.querySelectorAll('[data-daily]'))b.onclick=()=>this.daily(b.dataset.daily);},
 async daily(id){const h=this.esc,el=this.dialog('经营日报','<p role="status">正在读取归档日报…</p>');try{const [r,base]=await Promise.all([this.api('GET','daily-briefs?id='+encodeURIComponent(id)),Store._ensureClient()]);const response=await fetch(base+'/rest/v1/daily-briefs?id='+encodeURIComponent(id)+'&format=html',{headers:Auth.authHeaders()});if(!response.ok)throw Error('归档文件不可用，请稍后重试');const html=await response.text();if(!el.isConnected)return;el.querySelector('[role=status]').outerHTML='<p>'+h(r.date)+' · v'+h(r.revision)+' · '+h(this.dailyStatus(r))+'</p><p class="rh-muted">资料截止：'+h(r.cutoffTime||r.generatedAt||'未记录')+'</p><iframe class="rh-frame" title="已归档经营日报" sandbox></iframe><div class="rh-actions"><button class="rh-outline" id="rh-daily-download">下载HTML</button></div>';el.querySelector('iframe').srcdoc=html;el.querySelector('#rh-daily-download').onclick=()=>OperationsReportCenter.save(html,'经营日报-'+r.date+'-v'+r.revision+'.html','text/html;charset=utf-8');}catch(e){if(el.isConnected)el.querySelector('[role=status]').textContent=e.message;}},
 async archive(epoch){const h=this.esc,s={...this.state},type=s.kind==='daily'?'':s.kind;const q=new URLSearchParams({month:s.month,latest:'1',limit:20,offset:s.offset});if(type)q.set('type',type);if(s.query)q.set('search',s.query);
  const [r,d]=await Promise.all([s.kind==='daily'?Promise.resolve(null):this.api('GET','operations-reports?'+q),s.kind&&s.kind!=='daily'?Promise.resolve(null):this.api('GET','daily-briefs?month='+s.month+'&limit=50')]);if(epoch!==this.epoch)return;
  const days=(d?.reports||[]).filter(x=>(x.business_date+'经营日报').includes(s.query));
  this.$('content').innerHTML='<section class="rh-panel"><div class="rh-section-title"><h2>报告档案</h2><form id="rh-search-form"><input id="rh-search" type="search" maxlength="120" placeholder="日期或报告关键词" aria-label="搜索报告" value="'+h(s.query)+'"><button class="rh-outline">查询</button></form></div><div class="rh-filters">'+[['','全部'],['daily','日报'],['weekly','周报'],['monthly','月报'],['special','专项']].map(([v,n])=>'<button data-kind="'+v+'" aria-pressed="'+(s.kind===v)+'">'+n+'</button>').join('')+'</div><p class="rh-footnote">按'+h(s.month)+'查看最新版本，跨月周保持完整。日报暂报、修订状态单独标记。</p>'+(r?'<h3>正式分析报告</h3>'+this.reportRows(r.reports)+'<div class="rh-actions"><span>共'+r.total+'份</span><button class="rh-outline" id="rh-prev" '+(s.offset===0?'disabled':'')+'>上一页</button><button class="rh-outline" id="rh-next" '+(s.offset+20>=r.total?'disabled':'')+'>下一页</button></div>':'')+(d?'<h3>日报</h3>'+(days.length?days.map(x=>'<article class="rh-report-row"><div><b>'+h(x.business_date)+'</b><small>经营日报</small></div><span class="rh-badge '+(!x.finalized?'rh-amber':'')+'">'+h(this.dailyStatus(x))+'</span><button class="rh-text" data-daily="'+h(x.id)+'">阅读 →</button></article>').join(''):'<p class="rh-muted">暂无符合条件的归档日报；缺失不补零。</p>'):'')+'</section>';
  for(const b of this.$root.querySelectorAll('[data-kind]'))b.onclick=()=>{this.state.kind=b.dataset.kind;this.state.offset=0;this.load();};this.$('search-form').onsubmit=e=>{e.preventDefault();this.state.query=this.$('search').value.trim();this.state.offset=0;this.load();};this.$('prev')?.addEventListener('click',()=>{this.state.offset-=20;this.load();});this.$('next')?.addEventListener('click',()=>{this.state.offset+=20;this.load();});this.bindReports();this.bindDaily(this.$root);
 },
 targets(){const h=this.esc,m=this.money,d=this.summary,year=this.state.month.slice(0,4);this.$('content').innerHTML='<section class="rh-panel"><h2>月度收入目标</h2><p class="rh-muted">'+h(year)+'年 · 馆长设定，管理员维护。预测收入独立测算。</p>'+Array.from({length:12},(_,i)=>{const month=year+'-'+String(i+1).padStart(2,'0');return '<div class="rh-target-row"><b>'+(i+1)+'月</b><strong>'+m(d.targets[month])+'</strong><span class="rh-muted">'+(d.targets[month]!=null?'已设定':'等待设定')+'</span>'+(d.canSetTargets?'<button data-target="'+month+'" class="rh-text">'+(d.targets[month]!=null?'调整目标':'设置目标')+' →</button>':'')+'</div>';}).join('')+'<h3>调整记录</h3>'+(d.history.length?d.history.slice().reverse().map(x=>'<p class="rh-history">'+h(x.month)+' · '+m(x.previous)+' → '+m(x.amount)+'<small>'+h(x.reason)+' · '+h(x.actorName||'管理员')+' · '+h(new Date(x.createdAt).toLocaleString('zh-CN'))+'</small></p>').join(''):'<p class="rh-muted">尚无通过本入口保存的调整记录，已有目标保持原值。</p>')+'<p class="rh-footnote">共享目标用于后续日报、周报和月报。已发布报告、封存快照和历史预测不改写。</p></section>';for(const b of this.$root.querySelectorAll('[data-target]'))b.onclick=()=>this.target(b.dataset.target);},
 target(month){if(!this.summary?.canSetTargets)return;const d=this.summary,h=this.esc,old=d.targets[month],el=this.dialog(old==null?'设置月度目标':'调整月度目标','<form id="rh-target-form"><label for="rh-target-month">月份</label><input id="rh-target-month" type="month" value="'+h(month)+'" readonly><label for="rh-target-amount">收入目标（元）</label><input id="rh-target-amount" type="number" min="0.01" max="999999999" step="0.01" required value="'+(old??'')+'">'+(old==null?'':'<label for="rh-target-reason">调整原因</label><textarea id="rh-target-reason" maxlength="1000" rows="3" required></textarea>')+'<p class="rh-footnote">目标由馆长确定，AI不会为缩小预测差距而下调目标。保存保留调整记录。</p><p id="rh-target-status" role="status"></p><div class="rh-actions"><button class="rh-primary">保存目标</button></div></form>');
  el.querySelector('form').onsubmit=async e=>{e.preventDefault();if(this.busy)return;this.busy=true;for(const b of el.querySelectorAll('button'))b.disabled=true;const status=el.querySelector('[role=status]');status.textContent='正在保存…';try{await this.api('POST','report-center',{action:'set-target',month,amount:Number(el.querySelector('#rh-target-amount').value),reason:el.querySelector('textarea')?.value||'',version:d.version});this.close();await this.load();UI.toast('月度目标已保存，调整记录已留存。');}catch(e){status.textContent=e.message+'；可关闭后刷新数据再核对。';}finally{this.busy=false;for(const b of el.querySelectorAll('button'))b.disabled=false;}};
 }
};
if(typeof window!=='undefined')window.OperationsReportHub=OperationsReportHub;
